// Workflow Independiente de TikTok Developers (Content Posting API v2)
// Corre todos los dias a las 00:00 AM y publica un carrusel de fotos separado por CIUDAD.
// La primera foto (photo_cover_index = 0) es la Portada de la Ciudad con la Fecha Actual.
// Soporta modo MEDIA_UPLOAD (Borrador/Inbox con audio recomendado) y DIRECT_POST (con auto_add_music: true).

const data = $input.first().json.body || $input.first().json;
const cities = Array.isArray(data.cities) ? data.cities : [];

if (cities.length === 0) {
  return [{ json: { status: 'empty', message: 'No hay difusiones aprobadas pendientes para TikTok hoy.' } }];
}

const staticData = $getWorkflowStaticData('global');
const clientKey = $env.TIKTOK_CLIENT_KEY;
const clientSecret = $env.TIKTOK_CLIENT_SECRET;
const refreshToken = staticData.tiktokRefreshToken || $env.TIKTOK_REFRESH_TOKEN;
let accessToken = staticData.tiktokAccessToken || $env.TIKTOK_ACCESS_TOKEN;

// Por defecto usa MEDIA_UPLOAD (Borrador al celular sin requerir auditoria publica)
// Puedes cambiar TIKTOK_POST_MODE="DIRECT_POST" cuando tu app este auditada en TikTok Developers
const postMode = ($env.TIKTOK_POST_MODE || 'MEDIA_UPLOAD').toUpperCase();
const privacyLevel = $env.TIKTOK_PRIVACY_LEVEL || 'PUBLIC_TO_EVERYONE';
const webhookSecret = $env.N8N_WEBHOOK_SECRET;

// Si aun no tienes el token de TikTok configurado, sale limpiamente sin marcar error en la BD
if (!accessToken && (!clientKey || !clientSecret || !refreshToken)) {
  return [
    {
      json: {
        status: 'pending_token',
        message: 'Workflow listo. Configura TIKTOK_ACCESS_TOKEN (o TIKTOK_CLIENT_KEY + TIKTOK_CLIENT_SECRET + TIKTOK_REFRESH_TOKEN) en .env para activar el envio a TikTok.',
        citiesPending: cities.map((c) => ({ city: c.city, totalApproved: c.totalApproved })),
      },
    },
  ];
}

// Si no tenemos un accessToken activo o ya expiro, refrescamos con refresh_token y guardamos el nuevo refresh_token rotado
const nowMs = Date.now();
const tokenExpiresAt = staticData.tiktokTokenExpiresAt || 0;
if ((!accessToken || (tokenExpiresAt > 0 && nowMs >= tokenExpiresAt)) && clientKey && clientSecret && refreshToken) {
  try {
    const tokenRes = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://open.tiktokapis.com/v2/oauth/token/',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: new URLSearchParams({
        client_key: clientKey,
        client_secret: clientSecret,
        grant_type: 'refresh_token',
        refresh_token: refreshToken,
      }).toString(),
      json: true,
    });
    if (tokenRes && tokenRes.access_token) {
      accessToken = tokenRes.access_token;
      staticData.tiktokAccessToken = tokenRes.access_token;
      staticData.tiktokTokenExpiresAt = nowMs + ((tokenRes.expires_in || 86400) - 3600) * 1000;
    }
    if (tokenRes && tokenRes.refresh_token) {
      staticData.tiktokRefreshToken = tokenRes.refresh_token;
    }
  } catch (refreshErr) {
    if (!accessToken) {
      return [
        {
          json: {
            status: 'oauth_error',
            error: `No se pudo refrescar el token de TikTok: ${refreshErr.message || String(refreshErr)}`,
          },
        },
      ];
    }
  }
}

const results = [];

for (const cityBatch of cities) {
  const errors = [];
  let tiktokPublishId = null;

  // TikTok permite hasta 35 imagenes JPEG por carrusel.
  // Indice 0 = Portada de la ciudad con la fecha actual; Indices 1..N = Tarjetas de inmuebles aprobados
  const photoImages = (cityBatch.carouselImagesJpg || []).slice(0, 35);

  if (photoImages.length === 0) {
    continue;
  }

  try {
    const postInfo = postMode === 'DIRECT_POST'
      ? {
          title: cityBatch.tiktokTitle,
          description: cityBatch.tiktokDescription,
          privacy_level: privacyLevel,
          disable_comment: false,
          auto_add_music: true,
        }
      : {
          title: cityBatch.tiktokTitle,
          description: cityBatch.tiktokDescription,
        };

    const tiktokRes = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://open.tiktokapis.com/v2/post/publish/content/init/',
      headers: {
        Authorization: `Bearer ${accessToken}`,
        'Content-Type': 'application/json; charset=UTF-8',
      },
      body: {
        post_info: postInfo,
        source_info: {
          source: 'PULL_FROM_URL',
          photo_cover_index: 0,
          photo_images: photoImages,
        },
        post_mode: postMode,
        media_type: 'PHOTO',
      },
      json: true,
    });

    if (tiktokRes && tiktokRes.data && tiktokRes.data.publish_id) {
      tiktokPublishId = tiktokRes.data.publish_id;
    } else if (tiktokRes && tiktokRes.error && tiktokRes.error.code !== 'ok') {
      errors.push(`TikTok API (${cityBatch.city}): ${tiktokRes.error.message || tiktokRes.error.code}`);
    }
  } catch (err) {
    errors.push(`TikTok Error (${cityBatch.city}): ${err.message || String(err)}`);
  }

  if (tiktokPublishId && cityBatch.callbackUrl) {
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: cityBatch.callbackUrl,
        headers: {
          'X-Webhook-Secret': webhookSecret,
          'Content-Type': 'application/json',
        },
        body: {
          difusion_ids: cityBatch.diffusionIds,
          difusion_id: cityBatch.diffusionIds[0],
          ciudad: cityBatch.city,
          network: 'tiktok',
          estado: 'publicado',
          tiktok_post_id: tiktokPublishId,
          error: null,
        },
        json: true,
      });
    } catch (cbErr) {
      errors.push(`Callback TikTok Error (${cityBatch.city}): ${cbErr.message || String(cbErr)}`);
    }
  }

  results.push({
    json: {
      city: cityBatch.city,
      publicationDate: cityBatch.publicationDateDisplay,
      postMode,
      totalPhotosInCarousel: photoImages.length,
      tiktok_post_id: tiktokPublishId,
      errors,
    },
  });
}

return results;
